insert into public.categories (slug, name, description, image_url, position, is_active) values
  ('anime-figures', 'Anime Figures', 'Painted scale figures of original heroines, rogues and dreamers — sculpted for the display shelf.', '/images/categories/anime-figures.svg', 1, true),
  ('statues', 'Statues', 'Large-format polystone and resin statues with sculpted bases and museum-grade finishing.', '/images/categories/statues.svg', 2, true),
  ('chibi-minis', 'Chibi-Style Minis', 'Palm-sized, big-head minis with swappable faces and playful accessory sets.', '/images/categories/chibi-minis.svg', 3, true),
  ('action-figures', 'Action Figures', 'Highly articulated 1/12 figures with tooling details, alternate hands and effect parts.', '/images/categories/action-figures.svg', 4, true),
  ('preorders', 'Preorders', 'Reserve upcoming releases before allocation closes. Charged in demo mode only.', '/images/categories/preorders.svg', 5, true),
  ('limited-editions', 'Limited Editions', 'Numbered runs, exclusive paint schemes and once-only dioramas.', '/images/categories/limited-editions.svg', 6, true),
  ('display-cases', 'Display Cases', 'Dust-proof acrylic and glass cases with optional LED lighting for your centerpiece pieces.', '/images/categories/display-cases.svg', 7, true),
  ('accessories', 'Accessories', 'Stands, risers, backdrops and care kits to keep your collection looking new.', '/images/categories/accessories.svg', 8, true)
insert into public.brands (slug, name, description) values
  ('lumen-forge', 'Lumen Forge', 'Scale-figure studio known for translucent effect parts and luminous paint work.'),
  ('kitsune-atelier', 'Kitsune Atelier', 'Small-batch atelier focused on dynamic poses and fabric-like sculpting.'),
  ('moonpetal-toys', 'Moonpetal Toys', 'Makers of soft-palette chibi minis and character merchandise.'),
  ('orbit-works', 'Orbit Works', 'Engineering-first action figure brand with 30+ points of articulation.'),
  ('glasshaven-studio', 'Glasshaven Studio', 'Premium polystone statues and limited dioramas in numbered runs.'),
  ('ironbloom-collectibles', 'Ironbloom Collectibles', 'Mechanical designs, die-cast parts and weathered finishes.'),
  ('vault-select', 'Vault Select', 'Items sourced by the Nova Figure Vault team.'),
  ('vaultline-display', 'Vaultline Display Co.', 'Display cases, stands and care accessories designed for collectors.')
insert into public.products (slug, name, short_description, full_description, category_id, brand_id, franchise, sku, regular_price, sale_price, currency, inventory_quantity, status, badge, release_date, scale, material, dimensions, weight, featured, seo_title, seo_description, sales_count, created_at) values
  ('aiko-starfall-comet-gown', 'Aiko Starfall — Comet Gown Ver.', 'The star-reader of Starfall Requiem mid-twirl, her gown trailing a sculpted comet tail.', 'Aiko Starfall steps off the observatory stairs in her Comet Gown, one hand raised to catch a falling star. The skirt is sculpted in layered translucent PVC with a gradient that fades from midnight indigo to pale silver, and a clear comet-tail effect part sweeps behind her. A constellation-etched base completes the scene. The Deluxe edition adds an alternate smiling face, a star-chart backdrop card and an extra hand holding a lantern.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'lumen-forge'), 'Starfall Requiem', 'NFV-AF-0001', 189.99, null, 'USD', 14, 'active', 'new', '2026-09-12', '1/7', 'PVC, ABS', 'H 25 cm × W 18 cm × D 16 cm', '0.9 kg', true, 'Aiko Starfall — Comet Gown Ver. | Nova Figure Vault', 'The star-reader of Starfall Requiem mid-twirl, her gown trailing a sculpted comet tail.', 96, now() - interval '3 days'),
  ('ren-kurogane-neon-ronin', 'Ren Kurogane — Neon Ronin', 'A rain-soaked swordsman drawing a light-edged blade beneath a flickering city sign.', 'Ren Kurogane, the wandering guardian of Neon Ronin Chronicles, is captured in the instant before a duel. Rain streaks run along his coat in clear acrylic, and his blade is cast in a cyan translucent resin that catches light from every angle. The base recreates a wet rooftop with a hand-painted neon sign reflection.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'kitsune-atelier'), 'Neon Ronin Chronicles', 'NFV-AF-0002', 219.00, 179.00, 'USD', 11, 'active', 'sale', '2026-04-20', '1/7', 'PVC, ABS, clear acrylic', 'H 27 cm × W 22 cm × D 20 cm', '1.1 kg', true, 'Ren Kurogane — Neon Ronin | Nova Figure Vault', 'A rain-soaked swordsman drawing a light-edged blade beneath a flickering city sign.', 141, now() - interval '92 days'),
  ('mira-hanazono-petal-knight', 'Mira Hanazono — Petal Knight Uniform', 'The academy’s top fencing student salutes with a rose-gilded rapier.', 'Mira Hanazono stands at attention in the ceremonial Petal Knight uniform: a fitted navy jacket with gold piping, a pleated skirt with sculpted sakura embroidery and a rapier whose guard blooms into a rose. Her hair ribbon is a separate soft-PVC part that sways with the pose.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'moonpetal-toys'), 'Petal Knight Academy', 'NFV-AF-0003', 149.99, null, 'USD', 22, 'active', null, '2026-02-14', '1/8', 'PVC, ABS', 'H 21 cm × W 14 cm × D 14 cm', '0.6 kg', false, 'Mira Hanazono — Petal Knight Uniform | Nova Figure Vault', 'The academy’s top fencing student salutes with a rose-gilded rapier.', 74, now() - interval '160 days'),
  ('captain-selka-tidebreaker', 'Captain Selka — Tidebreaker', 'The submarine captain of Abyssal Tide bracing against a sculpted breaking wave.', 'Captain Selka plants her boots on the deck of the Tidebreaker as a wall of water curls overhead. The wave is a large translucent part with layered foam detail, and her die-cast compass pendant adds real heft. Preorder allocation is limited; the expected release window is March 2027.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'orbit-works'), 'Abyssal Tide', 'NFV-AF-0004', 239.00, null, 'USD', 30, 'active', 'preorder', '2027-03-15', '1/7', 'PVC, ABS, die-cast', 'H 29 cm × W 24 cm × D 21 cm', '1.3 kg', false, 'Captain Selka — Tidebreaker | Nova Figure Vault', 'The submarine captain of Abyssal Tide bracing against a sculpted breaking wave.', 38, now() - interval '6 days'),
  ('yuzu-clockwright-skyship-mechanic', 'Yuzu Clockwright — Skyship Mechanic', 'An airship engineer perched on a brass engine block, wrench in hand.', 'Yuzu Clockwright, chief mechanic of the skyship Marigold, sits cross-legged on a sculpted brass engine with gears you can trace from flywheel to piston. Grease smudges, goggles with clear lenses and a tiny clockwork bird companion round out the piece.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'kitsune-atelier'), 'Clockwork Sky', 'NFV-AF-0005', 175.00, null, 'USD', 0, 'active', 'sold_out', '2025-11-02', '1/7', 'PVC, ABS', 'H 23 cm × W 19 cm × D 17 cm', '0.8 kg', false, 'Yuzu Clockwright — Skyship Mechanic | Nova Figure Vault', 'An airship engineer perched on a brass engine block, wrench in hand.', 188, now() - interval '260 days'),
  ('hikari-ember-phoenix-dancer', 'Hikari Ember — Phoenix Dancer', 'A fire-dancer wreathed in translucent phoenix wings, frozen at the height of a spin.', 'Hikari Ember performs the Phoenix Rite in a whirl of flame. Her wings are cast in graduated orange-to-violet resin, and ember particles are suspended on near-invisible clear rods around the figure. Limited to a small production run with a numbered certificate.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'lumen-forge'), 'Emberheart Saga', 'NFV-AF-0006', 289.00, null, 'USD', 5, 'active', 'limited', '2026-07-30', '1/6', 'PVC, ABS, translucent resin', 'H 34 cm × W 30 cm × D 26 cm', '1.7 kg', true, 'Hikari Ember — Phoenix Dancer | Nova Figure Vault', 'A fire-dancer wreathed in translucent phoenix wings, frozen at the height of a spin.', 122, now() - interval '40 days'),
  ('noa-silvermoon-night-library', 'Noa Silvermoon — Night Library', 'A quiet archivist reading by moonlight atop a tower of sculpted books.', 'Noa Silvermoon, keeper of the Starfall archives, rests on a spiral stack of tomes with a crescent-moon lamp casting sculpted light across the pages. Each book spine features unique printed titles from the in-world library.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'moonpetal-toys'), 'Starfall Requiem', 'NFV-AF-0007', 165.00, 139.00, 'USD', 8, 'active', 'sale', '2026-01-18', '1/7', 'PVC, ABS', 'H 22 cm × W 20 cm × D 18 cm', '0.85 kg', false, 'Noa Silvermoon — Night Library | Nova Figure Vault', 'A quiet archivist reading by moonlight atop a tower of sculpted books.', 67, now() - interval '190 days'),
  ('kaito-vale-rooftop-duel', 'Kaito Vale — Rooftop Duel', 'Ren’s rival crouches on a rooftop ledge, twin tonfa crackling with static.', 'Kaito Vale drops into a low guard on the edge of a rain-slick rooftop. Static arcs are rendered as clear blue effect parts that clip onto each tonfa, and his scarf is sculpted mid-flutter. Displays perfectly opposite Ren Kurogane — Neon Ronin.', (select id from public.categories where slug = 'anime-figures'), (select id from public.brands where slug = 'orbit-works'), 'Neon Ronin Chronicles', 'NFV-AF-0008', 139.00, null, 'USD', 18, 'active', 'new', '2026-09-01', '1/8', 'PVC, ABS', 'H 20 cm × W 17 cm × D 15 cm', '0.55 kg', false, 'Kaito Vale — Rooftop Duel | Nova Figure Vault', 'Ren’s rival crouches on a rooftop ledge, twin tonfa crackling with static.', 21, now() - interval '9 days'),
  ('abyssal-empress-throne-of-coral', 'The Abyssal Empress — Throne of Coral', 'The ruler of the deep enthroned on living coral, lit from within by bioluminescent LEDs.', 'The Abyssal Empress lounges on a throne grown from coral and sunken shipwreck timber. Hidden USB-powered LEDs illuminate translucent jellyfish and anemone details around the base. Each statue is hand-finished and individually numbered.', (select id from public.categories where slug = 'statues'), (select id from public.brands where slug = 'glasshaven-studio'), 'Abyssal Tide', 'NFV-ST-0009', 749.00, null, 'USD', 3, 'active', 'limited', '2026-06-10', '1/4', 'Polystone, resin, LED', 'H 58 cm × W 42 cm × D 38 cm', '9.2 kg', true, 'The Abyssal Empress — Throne of Coral | Nova Figure Vault', 'The ruler of the deep enthroned on living coral, lit from within by bioluminescent LEDs.', 19, now() - interval '55 days'),
  ('emberheart-dragon-knight-statue', 'Emberheart Dragon Knight Statue', 'A knight in scorched plate armor rising from the coils of a slain ember-wyrm.', 'The Dragon Knight of the Emberheart Saga stands triumphant on the cooling coils of an ember-wyrm. Armor plates are finished with layered metallic paint and heat-tint gradients, and the wyrm’s scales glow through translucent resin cracks.', (select id from public.categories where slug = 'statues'), (select id from public.brands where slug = 'ironbloom-collectibles'), 'Emberheart Saga', 'NFV-ST-0010', 529.00, null, 'USD', 25, 'active', 'preorder', '2027-01-28', '1/6', 'Polystone, die-cast', 'H 48 cm × W 36 cm × D 30 cm', '7.4 kg', false, 'Emberheart Dragon Knight Statue | Nova Figure Vault', 'A knight in scorched plate armor rising from the coils of a slain ember-wyrm.', 26, now() - interval '12 days'),
  ('starfall-celestial-choir-diorama', 'Starfall Requiem — Celestial Choir Diorama', 'Three star-singers performing on a floating observatory platform.', 'A centerpiece diorama featuring three choir members of the Starfall Requiem suspended around a floating observatory. Acrylic star rings orbit the scene on hidden supports. This edition has fully sold through its production run.', (select id from public.categories where slug = 'statues'), (select id from public.brands where slug = 'glasshaven-studio'), 'Starfall Requiem', 'NFV-ST-0011', 899.00, null, 'USD', 0, 'active', 'sold_out', '2025-12-12', '1/6', 'Polystone, resin, acrylic', 'H 52 cm × W 60 cm × D 34 cm', '11 kg', false, 'Starfall Requiem — Celestial Choir Diorama | Nova Figure Vault', 'Three star-singers performing on a floating observatory platform.', 44, now() - interval '240 days'),
  ('clockwork-colossus-bust', 'Clockwork Colossus Bust', 'The guardian automaton of Clockwork Sky with exposed, rotating die-cast gears.', 'This 1/3 bust captures the Clockwork Colossus with its faceplate half-open to reveal working gears. Turn the key on the back and the gears rotate through the chest cavity. Weathered brass and verdigris finishes are hand-applied.', (select id from public.categories where slug = 'statues'), (select id from public.brands where slug = 'ironbloom-collectibles'), 'Clockwork Sky', 'NFV-ST-0012', 349.00, 299.00, 'USD', 7, 'active', 'sale', '2026-03-08', '1/3 bust', 'Polystone, die-cast gears', 'H 32 cm × W 28 cm × D 22 cm', '4.6 kg', false, 'Clockwork Colossus Bust | Nova Figure Vault', 'The guardian automaton of Clockwork Sky with exposed, rotating die-cast gears.', 52, now() - interval '130 days'),
  ('bloomguard-captain-statue', 'Petal Knight Captain — Bloomguard Statue', 'The academy’s captain of the guard, shield raised beneath an arch of blooming roses.', 'Captain Lysande of the Bloomguard stands beneath a sculpted rose arch with her heater shield raised. Over two hundred individually sculpted petals frame the statue, and the cape features a hand-painted academy crest.', (select id from public.categories where slug = 'statues'), (select id from public.brands where slug = 'glasshaven-studio'), 'Petal Knight Academy', 'NFV-ST-0013', 619.00, null, 'USD', 6, 'active', 'new', '2026-09-20', '1/4', 'Polystone, resin', 'H 55 cm × W 34 cm × D 34 cm', '8.1 kg', false, 'Petal Knight Captain — Bloomguard Statue | Nova Figure Vault', 'The academy’s captain of the guard, shield raised beneath an arch of blooming roses.', 8, now() - interval '2 days'),
  ('aiko-starfall-chibi-mini', 'Aiko Starfall Chibi Mini', 'Pocket-sized Aiko with three faces, a telescope and a sleepy comet plush.', 'The star-reader in chibi form! Includes three swappable faces (cheerful, focused, sleepy), a fold-out telescope, a tiny comet plush and a hinged neck joint for head tilts. Compatible with standard mini-figure stands.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Starfall Requiem', 'NFV-CM-0014', 54.99, null, 'USD', 40, 'active', null, '2026-05-05', 'Non-scale (approx. 10 cm)', 'PVC, ABS', 'H 10 cm × W 7 cm × D 7 cm', '0.15 kg', true, 'Aiko Starfall Chibi Mini | Nova Figure Vault', 'Pocket-sized Aiko with three faces, a telescope and a sleepy comet plush.', 210, now() - interval '70 days'),
  ('ren-kurogane-chibi-mini', 'Ren Kurogane Chibi Mini', 'Mini Ren with a bendable umbrella, glowing blade and a steaming noodle cup.', 'Ren takes a break between duels. This chibi mini includes a clear umbrella with a poseable handle, his cyan blade, a noodle-cup accessory with sculpted steam and three expressions including a determined glare.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Neon Ronin Chronicles', 'NFV-CM-0015', 54.99, 44.99, 'USD', 26, 'active', 'sale', '2026-04-12', 'Non-scale (approx. 10 cm)', 'PVC, ABS', 'H 10 cm × W 7 cm × D 7 cm', '0.15 kg', false, 'Ren Kurogane Chibi Mini | Nova Figure Vault', 'Mini Ren with a bendable umbrella, glowing blade and a steaming noodle cup.', 175, now() - interval '95 days'),
  ('mira-hanazono-chibi-mini', 'Mira Hanazono Chibi Mini', 'Fencing-practice Mira with a foam rapier, trophy and petal-burst effect.', 'Mira in her practice whites with a foam rapier, a tiny academy trophy and a clip-on petal-burst effect for victory poses. Preorders are expected to ship in February 2027.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Petal Knight Academy', 'NFV-CM-0016', 52.99, null, 'USD', 60, 'active', 'preorder', '2027-02-10', 'Non-scale (approx. 10 cm)', 'PVC, ABS', 'H 10 cm × W 7 cm × D 7 cm', '0.15 kg', false, 'Mira Hanazono Chibi Mini | Nova Figure Vault', 'Fencing-practice Mira with a foam rapier, trophy and petal-burst effect.', 30, now() - interval '4 days'),
  ('yuzu-clockwright-chibi-mini', 'Yuzu Clockwright Chibi Mini', 'Tiny mechanic Yuzu with an oversized wrench and a wind-up bird.', 'Yuzu in chibi form comes with an oversized wrench, interchangeable goggles (on head / over eyes) and her clockwork bird companion on a clear perch arm.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Clockwork Sky', 'NFV-CM-0017', 52.99, null, 'USD', 0, 'active', 'sold_out', '2025-10-22', 'Non-scale (approx. 10 cm)', 'PVC, ABS', 'H 10 cm × W 8 cm × D 7 cm', '0.16 kg', false, 'Yuzu Clockwright Chibi Mini | Nova Figure Vault', 'Tiny mechanic Yuzu with an oversized wrench and a wind-up bird.', 232, now() - interval '280 days'),
  ('pip-the-vault-sprite-chibi-mini', 'Pip the Vault Sprite Chibi Mini', 'Our own mascot: a little vault guardian holding a glowing key.', 'Pip is the Nova Figure Vault house mascot — a small sprite who guards collectors’ shelves at night. Includes a glow-in-the-dark key, a treasure chest accessory and two faces.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Vault Originals', 'NFV-CM-0018', 39.99, null, 'USD', 75, 'active', 'new', '2026-09-25', 'Non-scale (approx. 8 cm)', 'PVC, ABS', 'H 8 cm × W 7 cm × D 6 cm', '0.1 kg', false, 'Pip the Vault Sprite Chibi Mini | Nova Figure Vault', 'Our own mascot: a little vault guardian holding a glowing key.', 15, now() - interval '1 days'),
  ('selka-and-bubbles-chibi-set', 'Selka & Bubbles Chibi Mini Set', 'Captain Selka with her pufferfish first mate, Bubbles, in a two-figure set.', 'A two-figure set featuring a chibi Captain Selka and Bubbles, the inflatable pufferfish first mate. Bubbles comes in both deflated and fully puffed versions, plus a tiny ship’s wheel accessory.', (select id from public.categories where slug = 'chibi-minis'), (select id from public.brands where slug = 'moonpetal-toys'), 'Abyssal Tide', 'NFV-CM-0019', 64.99, null, 'USD', 19, 'active', null, '2026-06-28', 'Non-scale (approx. 10 cm)', 'PVC, ABS', 'H 10 cm × W 12 cm × D 8 cm', '0.22 kg', false, 'Selka & Bubbles Chibi Mini Set | Nova Figure Vault', 'Captain Selka with her pufferfish first mate, Bubbles, in a two-figure set.', 81, now() - interval '48 days'),
  ('neon-ronin-vanguard-action-figure', 'Neon Ronin Vanguard 1/12 Action Figure', 'A 32-point articulated armored vanguard with LED-ready visor and 9 hand pairs.', 'The Vanguard unit of Neon Ronin Chronicles features 32 points of articulation, diecast-feel POM joints, a removable visor with LED cavity, nine pairs of hands and three energy-blade effect parts. The Deluxe set adds a hover-bike and a flight stand.', (select id from public.categories where slug = 'action-figures'), (select id from public.brands where slug = 'orbit-works'), 'Neon Ronin Chronicles', 'NFV-AC-0020', 129.00, null, 'USD', 20, 'active', 'new', '2026-08-30', '1/12', 'PVC, ABS, POM joints', 'H 16 cm (figure) · box 30 × 20 × 8 cm', '0.45 kg', true, 'Neon Ronin Vanguard 1/12 Action Figure | Nova Figure Vault', 'A 32-point articulated armored vanguard with LED-ready visor and 9 hand pairs.', 64, now() - interval '14 days'),
  ('tidebreaker-marine-unit-action-figure', 'Tidebreaker Marine Unit 1/12 Action Figure', 'Deep-sea marine with harpoon rifle, rebreather helmet and swappable flippers.', 'Tidebreaker marines guard the submarine against abyssal threats. This 1/12 figure includes a harpoon rifle with extended line, a rebreather helmet with clear visor, swappable boots and flippers, and a coral display base.', (select id from public.categories where slug = 'action-figures'), (select id from public.brands where slug = 'orbit-works'), 'Abyssal Tide', 'NFV-AC-0021', 119.00, 95.00, 'USD', 16, 'active', 'sale', '2026-02-25', '1/12', 'PVC, ABS, POM joints', 'H 15.5 cm (figure)', '0.4 kg', false, 'Tidebreaker Marine Unit 1/12 Action Figure | Nova Figure Vault', 'Deep-sea marine with harpoon rifle, rebreather helmet and swappable flippers.', 58, now() - interval '150 days'),
  ('emberheart-lancer-action-figure', 'Emberheart Lancer 1/12 Action Figure', 'A flame-lance cavalier with die-cast pauldrons and fabric tabard.', 'The Emberheart Lancer features die-cast shoulder plates, a soft-goods tabard, a 30 cm flame lance with clear flame wrap and a kite shield with sculpted heraldry. Expected to ship in April 2027.', (select id from public.categories where slug = 'action-figures'), (select id from public.brands where slug = 'ironbloom-collectibles'), 'Emberheart Saga', 'NFV-AC-0022', 134.00, null, 'USD', 40, 'active', 'preorder', '2027-04-18', '1/12', 'PVC, ABS, die-cast', 'H 17 cm (figure)', '0.5 kg', false, 'Emberheart Lancer 1/12 Action Figure | Nova Figure Vault', 'A flame-lance cavalier with die-cast pauldrons and fabric tabard.', 22, now() - interval '5 days'),
  ('clockwork-sentinel-mech', 'Clockwork Sentinel Mech 1/12', 'A steam-powered sentinel with opening cockpit and rotating smoke-stack turret.', 'The Clockwork Sentinel stands guard over the skyship docks. The cockpit hatch opens to seat a 1/12 pilot, the smoke-stack turret rotates 360°, and the legs feature piston-linked articulation.', (select id from public.categories where slug = 'action-figures'), (select id from public.brands where slug = 'ironbloom-collectibles'), 'Clockwork Sky', 'NFV-AC-0023', 159.00, null, 'USD', 4, 'active', null, '2026-05-30', '1/12', 'ABS, die-cast, POM', 'H 22 cm × W 14 cm × D 12 cm', '0.8 kg', false, 'Clockwork Sentinel Mech 1/12 | Nova Figure Vault', 'A steam-powered sentinel with opening cockpit and rotating smoke-stack turret.', 47, now() - interval '66 days'),
  ('starfall-ranger-action-figure', 'Starfall Ranger 1/12 Action Figure', 'An observatory ranger with star-bow, quiver and constellation cloak.', 'The Starfall Ranger patrols the observatory perimeter. Includes a starlight bow with nocked-arrow part, a quiver of translucent arrows, a wired constellation cloak and five hand pairs.', (select id from public.categories where slug = 'action-figures'), (select id from public.brands where slug = 'orbit-works'), 'Starfall Requiem', 'NFV-AC-0024', 124.00, null, 'USD', 0, 'active', 'sold_out', '2025-09-14', '1/12', 'PVC, ABS, POM joints', 'H 16 cm (figure)', '0.42 kg', false, 'Starfall Ranger 1/12 Action Figure | Nova Figure Vault', 'An observatory ranger with star-bow, quiver and constellation cloak.', 156, now() - interval '300 days'),
  ('aiko-starfall-eclipse-armor', 'Aiko Starfall — Eclipse Armor Ver.', 'Aiko’s battle form: eclipse-black plate armor with a corona halo effect.', 'In the final act of Starfall Requiem, Aiko dons the Eclipse Armor. The plate armor uses vacuum-metallized parts, and a translucent corona halo floats behind her on a hidden arm. Release window: May 2027.', (select id from public.categories where slug = 'preorders'), (select id from public.brands where slug = 'lumen-forge'), 'Starfall Requiem', 'NFV-PO-0025', 259.00, null, 'USD', 50, 'active', 'preorder', '2027-05-20', '1/7', 'PVC, ABS, metallic plating', 'H 28 cm × W 24 cm × D 20 cm', '1.2 kg', true, 'Aiko Starfall — Eclipse Armor Ver. | Nova Figure Vault', 'Aiko’s battle form: eclipse-black plate armor with a corona halo effect.', 61, now() - interval '7 days'),
  ('kaito-vale-midnight-rain', 'Kaito Vale — Midnight Rain', 'Kaito off-duty under a transparent umbrella, city lights reflected below.', 'A quieter moment for Kaito Vale: hood up, umbrella tilted, standing over a puddle base that reflects a sculpted neon skyline. The umbrella canopy is clear PVC with printed raindrops.', (select id from public.categories where slug = 'preorders'), (select id from public.brands where slug = 'kitsune-atelier'), 'Neon Ronin Chronicles', 'NFV-PO-0026', 205.00, null, 'USD', 35, 'active', 'preorder', '2027-02-27', '1/7', 'PVC, ABS', 'H 26 cm × W 18 cm × D 18 cm', '1.0 kg', false, 'Kaito Vale — Midnight Rain | Nova Figure Vault', 'Kaito off-duty under a transparent umbrella, city lights reflected below.', 29, now() - interval '10 days'),
  ('noa-silvermoon-eternal-archive', 'Noa Silvermoon — Eternal Archive 1/6', 'Noa summoning a spiral of floating pages from the infinite archive.', 'Noa Silvermoon in a large 1/6 scale, surrounded by a spiral of acrylic pages that float on a central clear column. Each page is printed with original archive glyphs. Release window: June 2027.', (select id from public.categories where slug = 'preorders'), (select id from public.brands where slug = 'lumen-forge'), 'Starfall Requiem', 'NFV-PO-0027', 329.00, null, 'USD', 20, 'active', 'preorder', '2027-06-30', '1/6', 'PVC, ABS, acrylic', 'H 36 cm × W 30 cm × D 28 cm', '1.9 kg', false, 'Noa Silvermoon — Eternal Archive 1/6 | Nova Figure Vault', 'Noa summoning a spiral of floating pages from the infinite archive.', 17, now() - interval '11 days'),
  ('hikari-ember-gold-flame-exclusive', 'Hikari Ember — Gold Flame Exclusive', 'Vault-exclusive gold flame colorway, numbered to 500 pieces.', 'An exclusive repaint of Hikari Ember with gold-tone plated flames, a white ceremonial costume and a black lacquer base with gold numbering. Limited to 500 pieces worldwide, each with a certificate of authenticity.', (select id from public.categories where slug = 'limited-editions'), (select id from public.brands where slug = 'lumen-forge'), 'Emberheart Saga', 'NFV-LE-0028', 349.00, null, 'USD', 2, 'active', 'limited', '2026-08-15', '1/7', 'PVC, ABS, gold-tone plating', 'H 30 cm × W 26 cm × D 22 cm', '1.4 kg', true, 'Hikari Ember — Gold Flame Exclusive | Nova Figure Vault', 'Vault-exclusive gold flame colorway, numbered to 500 pieces.', 88, now() - interval '25 days'),
  ('ren-kurogane-chrome-edition-bust', 'Ren Kurogane — Chrome Edition Bust', 'A mirror-chrome bust of Ren, limited to 300 pieces — fully allocated.', 'Ren Kurogane rendered in a mirror-chrome finish over polystone, with only the eyes and neon visor stripe hand-painted. The edition of 300 is fully allocated.', (select id from public.categories where slug = 'limited-editions'), (select id from public.brands where slug = 'glasshaven-studio'), 'Neon Ronin Chronicles', 'NFV-LE-0029', 279.00, null, 'USD', 0, 'active', 'sold_out', '2026-03-30', '1/2 bust', 'Polystone, chrome finish', 'H 30 cm × W 24 cm × D 18 cm', '3.8 kg', false, 'Ren Kurogane — Chrome Edition Bust | Nova Figure Vault', 'A mirror-chrome bust of Ren, limited to 300 pieces — fully allocated.', 300, now() - interval '120 days'),
  ('vault-anniversary-crystal-diorama', 'Vault Anniversary Crystal Diorama', 'Pip guarding a crystal vault, lit by a color-shifting LED base.', 'Celebrating the Vault’s anniversary: Pip the Vault Sprite stands atop a faceted crystal vault door. The LED base cycles through purple, indigo and cyan. Numbered edition of 1,000.', (select id from public.categories where slug = 'limited-editions'), (select id from public.brands where slug = 'glasshaven-studio'), 'Vault Originals', 'NFV-LE-0030', 449.00, null, 'USD', 9, 'active', 'limited', '2026-10-01', 'Diorama', 'Resin, crystal-clear acrylic, LED', 'H 35 cm × W 40 cm × D 25 cm', '4.2 kg', false, 'Vault Anniversary Crystal Diorama | Nova Figure Vault', 'Pip guarding a crystal vault, lit by a color-shifting LED base.', 12, now() - interval '1 days'),
  ('aurora-led-display-case-single', 'Aurora LED Display Case — Single', 'A 3 mm UV-resistant acrylic case with a dimmable, color-tunable LED base.', 'Protect your centerpiece from dust and UV fading. The Aurora case uses 3 mm UV-resistant acrylic, magnetic lid closure and a USB-C LED base with warm, cool and RGB modes.', (select id from public.categories where slug = 'display-cases'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-DC-0031', 89.00, null, 'USD', 33, 'active', null, '2026-01-05', 'Fits up to 1/6', 'UV-resistant acrylic, aluminum LED base', 'H 40 cm × W 30 cm × D 30 cm', '2.6 kg', true, 'Aurora LED Display Case — Single | Nova Figure Vault', 'A 3 mm UV-resistant acrylic case with a dimmable, color-tunable LED base.', 133, now() - interval '200 days'),
  ('tower-vitrine-five-shelf-case', 'Tower Vitrine 5-Shelf Case', 'A tall tempered-glass vitrine with five adjustable shelves and a locking door.', 'The Tower Vitrine holds an entire series. Five height-adjustable tempered-glass shelves, a mirrored back panel, front-mounted LED strips and a keyed lock keep your collection safe and lit.', (select id from public.categories where slug = 'display-cases'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-DC-0032', 249.00, 209.00, 'USD', 10, 'active', 'sale', '2025-12-01', 'Fits 1/8 – 1/7 per shelf', 'Tempered glass, steel frame, LED strips', 'H 160 cm × W 42 cm × D 36 cm', '24 kg', false, 'Tower Vitrine 5-Shelf Case | Nova Figure Vault', 'A tall tempered-glass vitrine with five adjustable shelves and a locking door.', 39, now() - interval '230 days'),
  ('mini-shelf-riser-set', 'Mini Shelf Riser Set (3 pcs)', 'Stepped clear risers that turn a flat shelf into a stadium of minis.', 'Three stepped acrylic risers (2, 5 and 8 cm) let you stage rows of chibi minis without hiding anyone in the back. Polished edges and anti-slip feet.', (select id from public.categories where slug = 'display-cases'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-DC-0033', 34.99, null, 'USD', 80, 'active', 'new', '2026-09-18', 'Ideal for chibi minis', 'Clear acrylic', '30 × 10 cm, 3 tiers', '0.5 kg', false, 'Mini Shelf Riser Set (3 pcs) | Nova Figure Vault', 'Stepped clear risers that turn a flat shelf into a stadium of minis.', 26, now() - interval '8 days'),
  ('dust-guard-acrylic-cube-30', 'Dust-Guard Acrylic Cube 30 cm', 'A simple, crystal-clear cube cover with a matte black base.', 'A no-fuss display cube for 1/8 and 1/7 figures. The cover lifts straight off a recessed matte base, and the seams are solvent-welded for clarity.', (select id from public.categories where slug = 'display-cases'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-DC-0034', 59.00, null, 'USD', 45, 'active', null, '2025-08-20', 'Fits 1/8 – 1/7', 'Acrylic, black ABS base', 'H 30 cm × W 30 cm × D 30 cm', '1.8 kg', false, 'Dust-Guard Acrylic Cube 30 cm | Nova Figure Vault', 'A simple, crystal-clear cube cover with a matte black base.', 98, now() - interval '330 days'),
  ('gravity-stand-flight-base-kit', 'Gravity Stand Flight Base Kit', 'Adjustable clear flight stands with five clip adapters for mid-air poses.', 'Pose figures mid-leap. Includes two weighted clear bases, telescoping arms with three ball joints and five clip/peg adapters that fit most 1/12 and scale figures.', (select id from public.categories where slug = 'accessories'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-AX-0035', 24.99, null, 'USD', 120, 'active', null, '2025-07-10', 'Universal (1/12 – 1/7)', 'Acrylic, ABS clips', 'Base 12 cm, arm 8 – 18 cm', '0.2 kg', false, 'Gravity Stand Flight Base Kit | Nova Figure Vault', 'Adjustable clear flight stands with five clip adapters for mid-air poses.', 260, now() - interval '360 days'),
  ('microfiber-figure-care-kit', 'Microfiber Figure Care Kit', 'Brushes, cloths and swabs for safely dusting delicate paint and clear parts.', 'Everything you need for routine figure care: a goat-hair dusting brush, two microfiber cloths, precision swabs and a manual air blower, all in a zip pouch.', (select id from public.categories where slug = 'accessories'), (select id from public.brands where slug = 'vaultline-display'), null, 'NFV-AX-0036', 19.99, 15.99, 'USD', 90, 'active', 'sale', '2025-06-01', 'Universal', 'Microfiber, soft bristle, cotton', 'Pouch 18 × 12 cm', '0.12 kg', false, 'Microfiber Figure Care Kit | Nova Figure Vault', 'Brushes, cloths and swabs for safely dusting delicate paint and clear parts.', 310, now() - interval '390 days'),
  ('starfall-backdrop-card-set', 'Starfall Requiem Backdrop Card Set', 'Six illustrated night-sky backdrops sized for 1/7 and 1/8 displays.', 'Six double-sided, matte backdrop cards featuring original Starfall Requiem skyscapes. Includes two fold-out easel stands.', (select id from public.categories where slug = 'accessories'), (select id from public.brands where slug = 'lumen-forge'), 'Starfall Requiem', 'NFV-AX-0037', 14.99, null, 'USD', 150, 'active', 'new', '2026-09-10', 'Universal', 'Matte card stock', '6 cards, 30 × 20 cm', '0.18 kg', false, 'Starfall Requiem Backdrop Card Set | Nova Figure Vault', 'Six illustrated night-sky backdrops sized for 1/7 and 1/8 displays.', 34, now() - interval '6 days'),
