insert into public.reviews (product_id, author_name, rating, title, body, is_approved, created_at) values
  ((select id from public.products where slug = 'aiko-starfall-comet-gown'), 'Mika T.', 5, 'Even better in hand', 'Paint gradients are smooth and the sculpt holds up under close inspection. Arrived double-boxed without a scratch.', true, now() - interval '2 days'),
  ((select id from public.products where slug = 'aiko-starfall-comet-gown'), 'Leo M.', 4, 'Solid quality', 'Good weight, stable base, and the colors match the promo shots closely. Would buy from this line again.', true, now() - interval '1 days'),
  ((select id from public.products where slug = 'ren-kurogane-neon-ronin'), 'Elliot W.', 3, 'Nice, minor paint slop', 'Overall nice, but I spotted a small paint slip on the hem. Not noticeable from normal viewing distance.', true, now() - interval '91 days'),
  ((select id from public.products where slug = 'ren-kurogane-neon-ronin'), 'Ava L.', 5, 'Instant favorite', 'Bought it as a gift and ended up ordering a second one for myself. Customer support was quick and friendly.', true, now() - interval '89 days'),
  ((select id from public.products where slug = 'ren-kurogane-neon-ronin'), 'Ibrahim A.', 4, 'Sturdy and well made', 'No leaning after weeks on display. Base is heavy and the joints are tight.', true, now() - interval '87 days'),
  ((select id from public.products where slug = 'mira-hanazono-petal-knight'), 'Chloe N.', 5, 'Stunning lighting', 'With a backlight the translucent parts glow beautifully. Exactly the look I wanted for my display.', true, now() - interval '159 days'),
  ((select id from public.products where slug = 'mira-hanazono-petal-knight'), 'Jordan R.', 4, 'Great centerpiece', 'Looks fantastic on my shelf. One peg was a little tight, but a hair dryer fixed it in seconds.', true, now() - interval '157 days'),
